def solve_bt(idx, current_seq, remaining):
    if not remaining:
        return current_seq

    # Find the first empty spot
    while idx < 30 and current_seq[idx] != 0:
        idx += 1

    if idx == 30:
        return current_seq if not remaining else None

    for v in list(remaining):
        dist = v + 1
        if idx + dist < 30 and current_seq[idx + dist] == 0:
            current_seq[idx] = v
            current_seq[idx + dist] = v
            remaining.remove(v)

            res = solve_bt(idx + 1, current_seq, remaining)
            if res: return res

            remaining.add(v)
            current_seq[idx] = 0
            current_seq[idx + dist] = 0

    return None

