def solve_all():
    seq = [0] * 30
    for k, v in fixed.items():
        seq[k] = v

    # Check which numbers are fully placed, partially placed, or not placed
    counts = {i: 0 for i in range(1, 16)}
    for x in seq:
        if x != 0:
            counts[x] += 1

    # For partially placed, place the other one
    for v, c in counts.items():
        if c == 1:
            dist = v + 1
            # find the position
            pos = seq.index(v)
            p1 = pos - dist
            p2 = pos + dist
            can_p1 = p1 >= 0 and seq[p1] == 0
            can_p2 = p2 < 30 and seq[p2] == 0
            if can_p1 and not can_p2:
                seq[p1] = v
                counts[v] = 2
            elif can_p2 and not can_p1:
                seq[p2] = v
                counts[v] = 2
            elif can_p1 and can_p2:
                # This shouldn't happen if we just branch on numbers
                pass
            else:
                return None # UNSAT

    unplaced = [v for v, c in counts.items() if c == 0]
    partially_placed = [v for v, c in counts.items() if c == 1]

    def bt(unplaced_idx, part_idx):
        if part_idx < len(partially_placed):
            v = partially_placed[part_idx]
            dist = v + 1
            pos = seq.index(v)
            for p in (pos - dist, pos + dist):
                if 0 <= p < 30 and seq[p] == 0:
                    seq[p] = v
                    res = bt(unplaced_idx, part_idx + 1)
                    if res: return res
                    seq[p] = 0
            return None

        if unplaced_idx < len(unplaced):
            v = unplaced[unplaced_idx]
            dist = v + 1
            for i in range(30 - dist):
                if seq[i] == 0 and seq[i + dist] == 0:
                    seq[i] = v
                    seq[i + dist] = v
                    res = bt(unplaced_idx + 1, part_idx)
                    if res: return res
                    seq[i] = 0
                    seq[i + dist] = 0
            return None

        return list(seq)

    return bt(0, 0)

